template:
fn zero_ends(arr: &mut [i32]) {
    let mid = arr.len() / 2;
    let (left, right) = ⟦split_slot⟧;
    left[0] = 0;
    right[⟦idx_slot⟧] = 0;
}

fn main() {
    let mut data = [1, 2, 3, 4];
    zero_ends(&mut data);
}

tests:
#[test]
fn zeroes_both_ends() {
    let mut data = [1, 2, 3, 4];
    zero_ends(&mut data);
    assert_eq!(data, [0, 2, 3, 0]);
}
